    @Test
    void mnemonicVectors() {
        for (String[] v : BIP39) {
            byte[] entropy = Hash.fromHex(v[0]);
            assertEquals(v[1], Mnemonic.fromEntropy(entropy));
            assertArrayEquals(entropy, Mnemonic.toEntropy(v[1]));
            assertTrue(Mnemonic.isValid(v[1]));
            byte[] seed = Mnemonic.toSeed(v[1], "TREZOR");
            assertEquals(v[2], Hash.toHex(seed));
            assertEquals(v[3], Bip32.master(seed).toXprv());
        }
    }

    @Test
    void mnemonicRejectsBadInput() {
        String good = BIP39[0][1];
        assertFalse(Mnemonic.isValid(good.replace("about", "abandon")));
        assertFalse(Mnemonic.isValid(good.replace("about", "aboutx")));
        assertFalse(Mnemonic.isValid("abandon abandon abandon"));
        assertTrue(Mnemonic.isValid("  " + good.replace(" ", "\n  ") + " "));
        for (int strength = 128; strength <= 256; strength += 32) {
            String words = Mnemonic.generate(strength);
            assertEquals(strength / 32 * 3, words.split(" ").length);
            assertTrue(Mnemonic.isValid(words));
        }
        assertThrows(IllegalArgumentException.class, () -> Mnemonic.generate(100));
    }

    @Test
    void bip32Vectors() {
        Bip32 master = null;
        String seed = null;
        for (String[] v : BIP32) {
            if (!v[0].equals(seed)) {
                seed = v[0];
                master = Bip32.master(Hash.fromHex(seed));
            }
            Bip32 node = master.derive(v[1]);
            assertEquals(v[2], node.toXpub(), v[1]);
            assertEquals(v[3], node.toXprv(), v[1]);
            Bip32 parsed = Bip32.parse(v[3]);
            assertEquals(Bip32.XPRV, parsed.version());
            assertEquals(v[2], parsed.toXpub());
            assertEquals(v[2], Bip32.parse(v[2]).toXpub());
            assertFalse(Bip32.parse(v[2]).hasPrivateKey());
        }
    }

    @Test
    void publicDerivationMatchesPrivate() {
        Bip32 account = Bip32.master(Hash.fromHex(BIP32[0][0])).derive("m/44'/0'/0'");
        Bip32 watch = Bip32.parse(account.toXpub());
        for (int i = 0; i < 5; i++) {
            assertEquals(account.derive("0/" + i).toXpub(), watch.derive("0/" + i).toXpub());
        }
        assertThrows(IllegalStateException.class, () -> watch.child(Bip32.HARDENED));
    }

    @Test
    void slip10Vectors() {
        for (String[] v : SLIP10) {
            Slip10 node = Slip10.master(Hash.fromHex(v[0])).derive(v[1]);
            assertEquals(v[2], String.format("%08x", node.parentFingerprint()), v[1]);
            assertEquals(v[3], Hash.toHex(node.chainCode()), v[1]);
            assertEquals(v[4], Hash.toHex(node.privateKey()), v[1]);
            assertEquals(v[5], "00" + Hash.toHex(node.publicKey()), v[1]);
        }
    }

    @Test
    void derivationPaths() {
        assertEquals("m/44'/60'/0'/0/0", DerivationPath.parse("m/44h/60H/0'/0/0").toString());
        assertEquals(DerivationPath.bip44(60, 0, 0, 0), DerivationPath.parse("m/44'/60'/0'/0/0"));
        assertEquals(0, DerivationPath.parse("m").length());
        assertTrue(DerivationPath.parse("m/44'/501'/0'/0'").isFullyHardened());
        assertThrows(IllegalArgumentException.class, () -> DerivationPath.parse("m/x"));
        assertThrows(IllegalArgumentException.class, () -> DerivationPath.parse("m/2147483648"));
        assertThrows(IllegalArgumentException.class, () -> DerivationPath.parse("m//1"));
    }
